import {
    VlMap,
    VlMapBaseLayerGRBGray,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapSelectActions,
} from '@domg-wc/map';

// De features als GeoJSON-objecten, met coördinaten in Lambert 72 (EPSG:31370): één punt op layer-1, twee op layer-2.
document.querySelector('vl-map-features-layer[name="layer-1"]').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            id: 1,
            geometry: { type: 'Point', coordinates: [146055.0, 196908.0] },
        },
    ],
};
document.querySelector('vl-map-features-layer[name="layer-2"]').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            id: 2,
            geometry: { type: 'Point', coordinates: [149055.0, 199908.0] },
        },
        {
            type: 'Feature',
            id: 3,
            geometry: { type: 'Point', coordinates: [152055.0, 202908.0] },
        },
    ],
};

// vl-map-select-actions zoekt de lagen uit de property layers (hun name) enkel op wanneer het element aan de kaart
// gehangen wordt; layers achteraf zetten heeft geen effect. Maak het element daarom hier, zet layers en active, en
// hang het dan pas in vl-map.
const selectActions = document.createElement('vl-map-select-actions');
selectActions.layers = ['layer-1', 'layer-2'];
// De story zet de property active: die maakt de actie actief, ook als er al een andere actie van de kaart actief is.
// Het attribuut default-active activeert ze enkel als er nog geen andere actie actief is.
selectActions.active = true;
document.querySelector('vl-map').append(selectActions);

