const selectActions = document.createElement('vl-map-select-actions');
selectActions.layers = ['layer-1', 'layer-2'];
// De story zet de property active: die maakt de actie actief, ook als er al een andere actie van de kaart actief is.
// Het attribuut default-active activeert ze enkel als er nog geen andere actie actief is.
selectActions.active = true;
// De story zet ook het attribuut cluster op de actie; zie de notes voor wat dat in 2.4.0 doet.
selectActions.setAttribute('cluster', '');
// Bij clustering gebruik je best een vl-map-layer-circle-style in de actie: dan past de grootte van de selectie zich
// aan het aantal geclusterde features aan en wordt de tekst van de stijl getoond.
selectActions.innerHTML = `
    <vl-map-layer-circle-style
        color="#0099ff"
        text-color="#ffffff"
        border-color="#ffffff"
    ></vl-map-layer-circle-style>`;
document.querySelector('vl-map').append(selectActions);
